function encuadrarTrazado(a){const e=apex.region(a);e.element.off("apexafterrefresh.encuadrarTrazado").one("apexafterrefresh.encuadrarTrazado",function(){const a=e.mapData?.map?.bbox,r=e.getMapObject();if(!r||!Array.isArray(a))return void console.log("no es array",a);const o=a.flat();if(4!==o.length||!o.every(Number.isFinite))return void console.log("Las coordenadas");const[n,t,s,d]=o;n<-180||s>180||n>s||t<-90||d>90||t>d?console.log("Otra vez las coordenadas."):r.fitBounds([[n,t],[s,d]],{padding:40,maxZoom:14,duration:1e3,bearing:r.getBearing()})})}